-- ===========================================================================
-- Seed 27 : quizzes for the Go course
--
-- One per level. Like the other courses without a runner there is no
-- scratchpad on these pages: the playground cannot run Go, and an HTML
-- scratchpad under a Go question would be worse than none.
-- starter_for_course() in the website returns null for this course.
--
-- Generated by scratchpad/gen/build_batch5.py, which also checks that every
-- single_choice has exactly one correct option and every multiple_choice has
-- at least two. A quiz that cannot be passed is not obvious from the SQL.
-- ===========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-00000000002c',
   'c0000001-0000-4000-8000-00000000000e', 'e0000001-0000-4000-8000-0000000000bd',
   'Level 1 Check: Zero Values, Slices and Maps',
   'The zero value, no implicit conversions, and the slice aliasing that catches everyone. Every one of these can be settled with go run and five lines.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000002d',
   'c0000001-0000-4000-8000-00000000000e', 'e0000001-0000-4000-8000-0000000000be',
   'Level 2 Check: Methods, Interfaces and Errors',
   'Pointer against value receivers, implicit satisfaction, and errors as values.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000002e',
   'c0000001-0000-4000-8000-00000000000e', 'e0000001-0000-4000-8000-0000000000bf',
   'Level 3 Check: Goroutines, Channels and Context',
   'What blocks, who closes, and how a goroutine is told to stop.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000002f',
   'c0000001-0000-4000-8000-00000000000e', 'e0000001-0000-4000-8000-0000000000c0',
   'Expert Exam: Go',
   'Escape analysis, leaks, where the time goes, and how a module is arranged.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Zero Values, Slices and Maps
  ('a1000001-0000-4000-8000-0000000002d1', 'f0000001-0000-4000-8000-00000000002c', 'single_choice',
   'What happens when you read from a nil map, and when you write to one?',
   'Reading gives the zero value - no panic, which is why `m["missing"]` returning 0 is normal. Writing panics with "assignment to entry in nil map". A nil slice, by contrast, is usable for both reading and append. That asymmetry is the one to remember.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002d2', 'f0000001-0000-4000-8000-00000000002c', 'multiple_choice',
   'Which statements about slices are true? Select all that apply.',
   'A slice is a pointer, a length and a capacity pointing into an array, so two slices can share one array and see each other''s writes. append writes in place when there is capacity and allocates a new array when there is not - which is why you must always assign the result back. And a small slice of a large array keeps the whole array alive until you copy out of it.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002d3', 'f0000001-0000-4000-8000-00000000002c', 'single_choice',
   'Why does `var f float64 = someInt` not compile?',
   'Go has no implicit numeric conversions at all. You write `float64(someInt)`, every time. It is verbose on purpose: a conversion can lose data, and the language makes each one a decision you wrote down rather than one the compiler made for you.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002d4', 'f0000001-0000-4000-8000-00000000002c', 'single_choice',
   '`len("héllo")` returns what, and why?',
   '6. A Go string is a sequence of bytes holding UTF-8, and é takes two of them. `utf8.RuneCountInString` gives 5, and ranging over the string yields runes with their byte offsets - which is why the index in `for i, r := range s` jumps.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002d5', 'f0000001-0000-4000-8000-00000000002c', 'true_false',
   'A deferred call''s arguments are evaluated when the surrounding function returns.',
   'False. They are evaluated at the `defer` statement; only the call itself is postponed. So `defer fmt.Println(x)` prints the value x had when the defer ran, not when the function returned. Wrapping it in a closure - `defer func() { fmt.Println(x) }()` - is how you get the later value.',
   2, 5, NULL),

  -- Level 2 Check: Methods, Interfaces and Errors
  ('a1000001-0000-4000-8000-0000000002d6', 'f0000001-0000-4000-8000-00000000002d', 'single_choice',
   'When must a method use a pointer receiver?',
   'When it modifies the receiver - a value receiver gets a copy, so the change is discarded. Also when the struct contains a sync.Mutex or similar, because copying a mutex creates a different mutex and silently breaks the locking. Large structs are a third, weaker reason.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002d7', 'f0000001-0000-4000-8000-00000000002d', 'single_choice',
   'How does a type satisfy an interface in Go?',
   'By having the methods. There is no `implements` keyword and no declaration - which is what lets you define an interface for a type you do not own, and why interfaces are declared by the code that consumes them rather than next to the implementation.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002d8', 'f0000001-0000-4000-8000-00000000002d', 'single_choice',
   'A function returns `error`, and the implementation returns a nil `*MyError`. What does `err != nil` evaluate to?',
   'true - and this is Go''s most notorious gotcha. An interface value has a type and a value, and it is nil only when both are. A nil *MyError stored in an error interface has a type, so the interface is not nil. Never declare a typed nil and return it as an interface; return the literal nil.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002d9', 'f0000001-0000-4000-8000-00000000002d', 'multiple_choice',
   'Which are true about errors in Go? Select all that apply.',
   '%w wraps an error so the original stays reachable; errors.Is walks that chain for a sentinel, and errors.As walks it for a type. Comparing with == breaks as soon as any caller adds context, and comparing error strings breaks whenever a message is reworded. Each layer should add only what it knows.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002da', 'f0000001-0000-4000-8000-00000000002d', 'single_choice',
   'What is `panic` for?',
   'A bug: an impossible state, a broken invariant, a programming error. Expected failures are errors returned as values. recover belongs at a boundary - the top of a server goroutine, or a package converting a panic back into an error - and not in ordinary control flow.',
   3, 5, NULL),

  -- Level 3 Check: Goroutines, Channels and Context
  ('a1000001-0000-4000-8000-0000000002db', 'f0000001-0000-4000-8000-00000000002e', 'single_choice',
   'Your program ranges over a channel and never finishes. What is the most likely cause?',
   'Nobody closed the channel. `for v := range ch` ends when the channel is closed, and the sender is the one that closes it - conventionally with `defer close(ch)` right after starting to send. It is the commonest Go concurrency bug and it is completely silent.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002dc', 'f0000001-0000-4000-8000-00000000002e', 'multiple_choice',
   'Which statements about goroutines and channels are true? Select all that apply.',
   'A send on an unbuffered channel blocks until a receiver is ready - it is a synchronisation point, not merely a queue. Nothing waits for a goroutine: main returning ends the program regardless. A select with a default never blocks. And closing a channel twice panics, which is why exactly one sender should own the close.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002dd', 'f0000001-0000-4000-8000-00000000002e', 'single_choice',
   'What is a `context.Context` for?',
   'Carrying cancellation, deadlines and request-scoped values across API boundaries. A goroutine watches ctx.Done() in a select and returns when it fires. Pass it as the first parameter, never store it in a struct, and always `defer cancel()` after creating one with a timeout.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002de', 'f0000001-0000-4000-8000-00000000002e', 'single_choice',
   'When should you use a mutex rather than a channel?',
   'When several goroutines share one piece of state. A channel is for handing a value from one goroutine to another; a mutex is for protecting state that stays where it is. Using a channel to guard a shared counter is slower and harder to read than sync.Mutex, and both are idiomatic in their place.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002df', 'f0000001-0000-4000-8000-00000000002e', 'true_false',
   'A goroutine blocked forever on a channel is eventually cleaned up by the runtime.',
   'False. It is a leak: the goroutine, its stack, and everything its closure references stay in memory for the life of the process. Whoever starts a goroutine is responsible for how it ends - a context, a done channel, or a closed input, but always something.',
   2, 5, NULL),

  -- Expert Exam: Go
  ('a1000001-0000-4000-8000-0000000002e0', 'f0000001-0000-4000-8000-00000000002f', 'single_choice',
   'Returning `&localStruct` from a function - is it safe, and what does it cost?',
   'Safe, and it costs an allocation. Go''s escape analysis notices the pointer outlives the frame and moves the value to the heap. That removes a whole class of C bug at the price of an allocation you may not have intended - `go build -gcflags=-m` is how you find the ones you did not.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002e1', 'f0000001-0000-4000-8000-00000000002f', 'single_choice',
   'You append a million elements to a slice created with `[]int{}`. What is the cheap fix?',
   '`make([]int, 0, 1_000_000)`. append doubles the backing array when it runs out, so growing to a million copies roughly two million elements. Preallocating the capacity does none of that copying - and the same applies to `make(map[K]V, n)`.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002e2', 'f0000001-0000-4000-8000-00000000002f', 'single_choice',
   'What does the `internal/` directory do in a Go module?',
   'The compiler refuses any import of it from outside the module. It is real, enforced privacy at the package level - which makes it the simplest way to have a small public API and keep everything else free to change without breaking anyone.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002e3', 'f0000001-0000-4000-8000-00000000002f', 'single_choice',
   'Where should an interface be declared, in idiomatic Go?',
   'In the package that consumes it, and as small as that need. Because satisfaction is implicit, the implementing package never imports the interface - so the dependency arrow points the way you want without any ceremony. "Accept interfaces, return structs" follows from the same rule.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002e4', 'f0000001-0000-4000-8000-00000000002f', 'multiple_choice',
   'Which are part of a Go project that stays easy to change? Select all that apply.',
   'Dependencies passed in rather than reached for is what makes a package testable without a database or a clock. Table-driven tests with t.Run make adding a case one line. And gofmt, go vet and -race in CI settle formatting and catch what tests miss. A package that calls time.Now() directly cannot be tested deterministically.',
   3, 5, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation),
  points = VALUES(points), `position` = VALUES(`position`);

DELETE FROM assessment_question_options
