    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d8', 'true, because the interface holds a type even though the pointer is nil', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d8', 'false, because the pointer is nil', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d8', 'It panics at the comparison', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d8', 'It depends on whether MyError implements Error with a pointer receiver', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d9', 'fmt.Errorf with %w wraps, keeping the original reachable', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d9', 'errors.Is finds a sentinel through the wrap chain', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d9', 'errors.As finds a specific error type and binds it', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d9', 'Comparing err.Error() strings is a reliable way to identify an error', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002da', 'Bugs and impossible states, not expected failures', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002da', 'Any error a function cannot handle itself', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002da', 'Reporting invalid input from a caller', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002da', 'Unwinding to the nearest recover, like an exception', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002db', 'The sender never closed the channel', 1, 1
