    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002dc', 'A send on an unbuffered channel blocks until a receiver is ready', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002dc', 'Nothing waits for a goroutine unless you arrange it', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002dc', 'A select with a default case never blocks', 1, 3
