    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002dd', 'Cancellation and deadlines, passed down and watched via ctx.Done()', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002dd', 'Storing shared mutable state between goroutines safely', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002dd', 'Limiting how many goroutines the runtime will create', 0, 3
