    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e0', 'Safe and free: Go always heap-allocates structs', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e0', 'It does not compile - Go forbids returning a pointer to a local', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e1', 'make([]int, 0, n) so the backing array is allocated once', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e1', 'Use a linked list instead, which never copies', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e1', 'Call runtime.GC() periodically to compact it', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e1', 'Append in a goroutine so the copying overlaps', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e2', 'Nothing outside the module can import anything under it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e2', 'It marks packages that are excluded from the build', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e2', 'It is a convention only, with no compiler support', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e2', 'It stops the package being included in the binary', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e3', 'In the consuming package, as small as the need - the implementer never imports it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e3', 'Next to the implementation, so they stay in sync', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e3', 'In a shared interfaces package both sides import', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e3', 'In the package with the most implementations of it', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e4', 'Dependencies are passed in, so a test can supply a fake clock', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e4', 'Table-driven tests with t.Run, so a new case is one line', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e4', 'gofmt, go vet and go test -race enforced in CI', 1, 3
